import { DAY, DEFAULT_POLICIES, clock } from './core';
import { DEFAULT_TZ, dayKey } from './format';
import * as S from './services';
import type { DB, ID, User } from './types';

/**
 * Reproducible demo data. History is generated by TIME-TRAVELLING the clock and calling the real
 * service layer — so every seeded booking, result, badge and case went through the same validation,
 * state machine, audit log and notifications as a live action. All names are fictional SAMPLE data.
 */

const MIN = 60_000;

function local(instant: number) {
  const d = new Date(instant);
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: DEFAULT_TZ, hour: '2-digit', minute: '2-digit', hour12: false }).format(d);
  return { date: dayKey(d), hhmm: parts };
}
const addMin = (hhmm: string, m: number) => { const [h, mm] = hhmm.split(':').map(Number); const t = h * 60 + mm + m; return `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}`; };

export function createSeed(nowMs: number = Date.now()): DB {
  const db: DB = {
    version: 1, seq: 0, users: [], students: [], interviewers: [], tracks: [], badgeDefs: [], skills: [], badgeSkillReqs: [],
    skillProgress: [], windows: [], slots: [], bookings: [], attempts: [], studentBadges: [], malpracticeCases: [],
    notifications: [], auditLogs: [], policies: { ...DEFAULT_POLICIES },
  };
  const at = <T>(ms: number, fn: () => T): T => { clock.set(new Date(ms)); try { return fn(); } finally { clock.set(null); } };
  const NOW = Math.ceil(nowMs / (5 * MIN)) * 5 * MIN;
  const daysAgo = (d: number) => NOW - d * DAY;

  // ── Catalogue ──
  const tracks = [
    { id: 'trk_prod', name: 'AI Product Mastery', description: 'Ship AI-powered products end to end.' },
    { id: 'trk_sys', name: 'AI Systems Mastery', description: 'Build reliable AI systems and infrastructure.' },
    { id: 'trk_mod', name: 'AI Models Mastery', description: 'Train, evaluate and fine-tune models.' },
  ];
  db.tracks = tracks;
  const skillNames: Record<string, string[]> = {
    trk_prod: ['Product Discovery', 'Prompt Design', 'AI UX Patterns', 'Evaluation & Metrics'],
    trk_sys: ['APIs & Backends', 'Vector Databases', 'LLM Ops', 'Scaling & Cost'],
    trk_mod: ['Python for ML', 'Classical ML', 'Deep Learning', 'Fine-tuning'],
  };
  for (const t of tracks) {
    skillNames[t.id].forEach((n, i) => db.skills.push({ id: `${t.id.replace('trk_', 'sk_')}${i + 1}`, trackId: t.id, name: n }));
    db.badgeDefs.push({ id: `${t.id.replace('trk_', 'bd_')}_nov`, trackId: t.id, level: 'Novice', name: `${t.name} — Novice`, order: 1 });
    db.badgeDefs.push({ id: `${t.id.replace('trk_', 'bd_')}_mas`, trackId: t.id, level: 'Master', name: `${t.name} — Master`, order: 2 });
    const sk = (i: number) => `${t.id.replace('trk_', 'sk_')}${i}`;
    db.badgeSkillReqs.push({ badgeDefId: `${t.id.replace('trk_', 'bd_')}_nov`, skillId: sk(1) }, { badgeDefId: `${t.id.replace('trk_', 'bd_')}_nov`, skillId: sk(2) });
    db.badgeSkillReqs.push({ badgeDefId: `${t.id.replace('trk_', 'bd_')}_mas`, skillId: sk(3) }, { badgeDefId: `${t.id.replace('trk_', 'bd_')}_mas`, skillId: sk(4) });
  }

  // ── People ──
  const addUser = (id: ID, fullName: string, role: User['role'], permissions?: User['permissions']) => {
    db.users.push({ id, fullName, email: `${fullName.split(' ')[0].toLowerCase()}@demo.grit.example`, role, isActive: true, permissions });
  };
  addUser('u_admin1', 'Priya Menon', 'ADMIN', { reviewMalpractice: true, editSettings: true });
  addUser('u_admin2', 'Karan Shah', 'ADMIN', {});
  const ivs = [
    ['iv_meera', 'Meera Iyer', 'AI Product'], ['iv_rahul', 'Rahul Verma', 'AI Systems'],
    ['iv_sana', 'Sana Khan', 'AI Models'], ['iv_arjun', 'Arjun Nair', 'AI Product & Systems'],
  ];
  ivs.forEach(([id, name, spec], i) => { addUser(`u_${id}`, name, 'INTERVIEWER'); db.interviewers.push({ id, userId: `u_${id}`, employeeCode: `INT-${101 + i}`, specialization: spec, isActive: true, timezone: DEFAULT_TZ }); });

  const studentDefs: [string, string][] = [
    ['Aarav Sharma', 'trk_prod'], ['Riya Patel', 'trk_prod'], ['Kabir Singh', 'trk_prod'], ['Ananya Reddy', 'trk_prod'],
    ['Vihaan Gupta', 'trk_sys'], ['Ishita Rao', 'trk_sys'], ['Arjun Mehta', 'trk_sys'], ['Diya Nair', 'trk_mod'],
    ['Rohan Das', 'trk_mod'], ['Saanvi Kulkarni', 'trk_mod'], ['Aditya Joshi', 'trk_prod'], ['Meher Kapoor', 'trk_sys'],
    ['Nikhil Bansal', 'trk_mod'], ['Tara Menon', 'trk_prod'], ['Yash Agarwal', 'trk_sys'], ['Zara Sheikh', 'trk_mod'],
    ['Kavya Pillai', 'trk_prod'], ['Dev Malhotra', 'trk_sys'], ['Myra Chopra', 'trk_mod'], ['Reyansh Iyer', 'trk_sys'],
  ];
  const campuses = ['NIAT Hyderabad', 'NIAT Bengaluru', 'NIAT Pune', 'NIAT Chennai'];
  const sid: Record<string, ID> = {};
  studentDefs.forEach(([name, track], i) => {
    const id = `st_${String(i + 1).padStart(2, '0')}`; sid[name.split(' ')[0]] = id;
    addUser(`u_${id}`, name, 'STUDENT');
    db.students.push({ id, userId: `u_${id}`, studentCode: `NIAT${24}${String(1001 + i)}`, campus: campuses[i % 4], batch: 2024 + (i % 2), timezone: DEFAULT_TZ });
    // progress row for each skill in the track (track membership)
    for (let k = 1; k <= 4; k++) db.skillProgress.push({ studentId: id, skillId: `${track.replace('trk_', 'sk_')}${k}`, status: 'NOT_STARTED' });
  });
  const trackOf = (first: string) => studentDefs.find(d => d[0].startsWith(first))![1];
  const nov = (first: string) => `${trackOf(first).replace('trk_', 'bd_')}_nov`;
  const skill = (first: string, k: number) => `${trackOf(first).replace('trk_', 'sk_')}${k}`;
  const ADMIN = 'u_admin1';
  const clear = (first: string, k: number, when: number) => at(when, () => S.recordSkillCleared(db, S.SYSTEM_ACTOR, sid[first], skill(first, k)));
  const inProgress = (first: string, k: number) => { const p = db.skillProgress.find(x => x.studentId === sid[first] && x.skillId === skill(first, k))!; p.status = 'IN_PROGRESS'; };

  // ── Availability (created 30 days ago so past + future windows are all valid at creation time) ──
  const T0 = daysAgo(30);
  const win = (iv: string, startMs: number, durMin: number) => {
    const s = local(startMs); const end = addMin(s.hhmm, durMin);
    if (end <= s.hhmm) return; // would cross midnight — skip in seed
    try { at(T0, () => S.addAvailability(db, `u_${iv}`, { interviewerId: iv, date: s.date, start: s.hhmm, end })); } catch { /* overlap in seed → skip */ }
  };
  const dayAt = (offset: number, hhmm: string) => { const base = local(NOW + offset * DAY).date; const [h, m] = hhmm.split(':').map(Number); return new Date(`${base}T${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:00+05:30`).getTime(); };
  for (let o = 1; o <= 14; o++) {
    if (o % 2 === 1) win('iv_meera', dayAt(o, '10:00'), 120);
    if (o % 2 === 0) win('iv_rahul', dayAt(o, '14:00'), 180);
    if (o % 3 === 0) win('iv_sana', dayAt(o, '16:00'), 120);
    win('iv_arjun', dayAt(o, '18:00'), 80);
  }
  win('iv_rahul', dayAt(1, '18:00'), 80);            // same time as Arjun tomorrow → reassignment is possible
  // Today, around "now", for the interviewer demo
  const todayDev = NOW - 140 * MIN, todayRiya = NOW + 20 * MIN, todayKabir = NOW + 55 * MIN, todayOpen = NOW + 95 * MIN;
  [todayDev, todayRiya, todayKabir, todayOpen].forEach(t => win('iv_meera', t, 30));
  // Past windows for history
  const past: Record<string, [string, number]> = {
    Reyansh1: ['iv_rahul', dayAt(-26, '14:00')], Reyansh2: ['iv_rahul', dayAt(-18, '14:00')], Reyansh3: ['iv_arjun', dayAt(-11, '18:00')],
    Aditya: ['iv_meera', dayAt(-15, '10:00')], Meher: ['iv_rahul', dayAt(-12, '14:00')], Saanvi: ['iv_sana', dayAt(-10, '16:00')],
    Ishita: ['iv_rahul', dayAt(-9, '14:00')], ArjunM: ['iv_arjun', dayAt(-8, '18:00')], Ananya: ['iv_meera', dayAt(-8, '10:00')],
    Diya: ['iv_sana', dayAt(-4, '16:00')], Vihaan: ['iv_rahul', dayAt(-2, '14:00')], Nikhil: ['iv_sana', dayAt(-1, '10:00')],
    Zara: ['iv_sana', dayAt(-1, '16:00')],
  };
  Object.values(past).forEach(([iv, t]) => win(iv, t, 30));

  const slotAt = (iv: string, t: number) => db.slots.find(s => s.interviewerId === iv && s.startAt === new Date(t).toISOString())!;
  const book = (first: string, badge: ID, iv: string, t: number, when: number) =>
    at(when, () => S.bookSlot(db, `u_${sid[first]}`, { studentId: sid[first], badgeDefId: badge, slotId: slotAt(iv, t).id }));
  const attOf = (bookingId: ID) => db.attempts.find(a => a.bookingId === bookingId)!;
  const run = (first: string, badge: ID, iv: string, t: number, outcome: 'PASS' | 'FAIL' | 'RETAKE_LATER', feedback: string, scores: [number, number, number]) => {
    const b = book(first, badge, iv, t, t - 2 * DAY);
    const a = attOf(b.id);
    at(t + 2 * MIN, () => S.startInterview(db, `u_${iv}`, a.id));
    at(t + 28 * MIN, () => S.submitOutcome(db, `u_${iv}`, a.id, { outcome, feedback, scores: { technical: scores[0], communication: scores[1], problemSolving: scores[2] } }));
    return a;
  };

  // ── Skill clears (eligibility is computed from these) ──
  const fullyNovice = ['Aarav', 'Riya', 'Kabir', 'Ananya', 'Vihaan', 'Ishita', 'Arjun', 'Diya', 'Saanvi', 'Aditya', 'Meher', 'Nikhil', 'Tara', 'Yash', 'Zara', 'Kavya', 'Dev', 'Myra', 'Reyansh'];
  fullyNovice.forEach((f, i) => { clear(f, 1, daysAgo(40 - (i % 6))); clear(f, 2, daysAgo(33 - (i % 3))); });
  clear('Rohan', 1, daysAgo(12)); inProgress('Rohan', 2);

  // ── Histories ──
  run('Reyansh', nov('Reyansh'), 'iv_rahul', past.Reyansh1[1], 'RETAKE_LATER', 'Good fundamentals but could not explain trade-offs between vector index types. Revisit HNSW vs IVF.', [3, 3, 2]);
  run('Reyansh', nov('Reyansh'), 'iv_rahul', past.Reyansh2[1], 'RETAKE_LATER', 'Better on indexes; API design answers were still vague on error handling and idempotency.', [3, 3, 3]);
  run('Reyansh', nov('Reyansh'), 'iv_arjun', past.Reyansh3[1], 'FAIL', 'Struggled with the live debugging task and could not complete the basic endpoint within time.', [2, 3, 2]);

  const aditya = run('Aditya', nov('Aditya'), 'iv_meera', past.Aditya[1], 'PASS', 'Strong product sense; excellent prompt iteration walkthrough.', [5, 4, 4]);
  const meher = run('Meher', nov('Meher'), 'iv_rahul', past.Meher[1], 'PASS', 'Solid backend design and clear explanations.', [4, 4, 4]);
  const saanvi = run('Saanvi', nov('Saanvi'), 'iv_sana', past.Saanvi[1], 'PASS', 'Clean modelling approach and good evaluation discipline.', [4, 5, 4]);
  run('Ishita', nov('Ishita'), 'iv_rahul', past.Ishita[1], 'RETAKE_LATER', 'Nearly there — revise vector database indexing and come back with one project you can demo end to end.', [3, 4, 3]);
  run('Arjun', nov('Arjun'), 'iv_arjun', past.ArjunM[1], 'RETAKE_LATER', 'Clear communication. Needs deeper understanding of caching and rate limits for LLM APIs.', [3, 4, 3]);
  run('Ananya', nov('Ananya'), 'iv_meera', past.Ananya[1], 'PASS', 'Excellent discovery interview walkthrough; crisp metrics thinking.', [5, 5, 4]);
  run('Diya', nov('Diya'), 'iv_sana', past.Diya[1], 'FAIL', 'Could not explain bias/variance or choose an evaluation metric for an imbalanced dataset.', [2, 3, 2]);
  run('Vihaan', nov('Vihaan'), 'iv_rahul', past.Vihaan[1], 'RETAKE_LATER', 'Good API work; revisit LLM ops basics (prompt caching, retries, observability).', [3, 3, 3]);

  // Nikhil — no-show yesterday
  { const b = book('Nikhil', nov('Nikhil'), 'iv_sana', past.Nikhil[1], past.Nikhil[1] - 3 * DAY); at(past.Nikhil[1] + 15 * MIN, () => S.markStudentNoShow(db, 'u_iv_sana', attOf(b.id).id)); }
  // Zara — interview started yesterday, outcome never recorded (interviewer forgot)
  { const b = book('Zara', nov('Zara'), 'iv_sana', past.Zara[1], past.Zara[1] - 2 * DAY); at(past.Zara[1] + 3 * MIN, () => S.startInterview(db, 'u_iv_sana', attOf(b.id).id)); }
  // Dev — passed earlier today with Meera
  run('Dev', nov('Dev'), 'iv_meera', todayDev, 'PASS', 'Confident systems answers; good grasp of cost trade-offs.', [4, 4, 5]);
  // Upcoming
  book('Riya', nov('Riya'), 'iv_meera', todayRiya, daysAgo(3));
  book('Kabir', nov('Kabir'), 'iv_meera', todayKabir, daysAgo(2));
  book('Kavya', nov('Kavya'), 'iv_arjun', dayAt(1, '18:00'), daysAgo(1));
  book('Arjun', nov('Arjun'), 'iv_rahul', dayAt(2, '14:40'), daysAgo(1));   // retake booked (attempt 2)
  // Myra — interviewer became unavailable, no colleague free → cancelled with priority rebooking
  { const b = book('Myra', nov('Myra'), 'iv_sana', dayAt(3, '16:00'), daysAgo(4)); at(daysAgo(1), () => S.interviewerUnavailable(db, 'u_iv_sana', attOf(b.id).id, 'Conducting a campus hiring drive')); }

  // Masters progress for badge holders
  clear('Ananya', 3, daysAgo(3)); inProgress('Ananya', 4);
  inProgress('Dev', 3);

  // ── Malpractice ──
  const sbOf = (a: { id: ID }) => db.studentBadges.find(b => b.attemptId === a.id)!.id;
  // Aditya: confirmed → nullified
  const c1 = at(daysAgo(8), () => S.flagMalpractice(db, 'u_iv_meera', sbOf(aditya), 'Identical code submission found in a later skill contest re-check; matches another student line-for-line.', 'Contest re-check report #RC-0412'));
  at(daysAgo(7), () => S.startInvestigation(db, ADMIN, c1, 'Requested contest logs and proctoring recording.'));
  at(daysAgo(5), () => S.decideCase(db, ADMIN, c1, 'CONFIRMED', 'Proctoring logs show a second person answering during the live interview; plagiarism confirmed by contest team.'));
  // Meher: dismissed → reinstated
  const c2 = at(daysAgo(6), () => S.flagMalpractice(db, 'u_admin2', sbOf(meher), 'Automated similarity alert on interview take-home snippet.', 'Similarity alert SA-2291'));
  at(daysAgo(5), () => S.startInvestigation(db, ADMIN, c2, 'Comparing against public sources.'));
  at(daysAgo(4), () => S.decideCase(db, ADMIN, c2, 'DISMISSED', 'Matched snippet is boilerplate from official framework docs; no malpractice.'));
  // Saanvi: two flags, one under investigation
  const c3 = at(daysAgo(2), () => S.flagMalpractice(db, 'u_iv_sana', sbOf(saanvi), 'Student appeared to read answers off-screen during the live interview.', 'Interview recording 00:14:10–00:19:45'));
  at(daysAgo(1), () => S.startInvestigation(db, ADMIN, c3, 'Reviewing interview recording.'));
  at(daysAgo(1) + 2 * 3_600_000, () => S.flagMalpractice(db, 'u_admin2', sbOf(saanvi), 'Peer report alleging shared answer sheet for the Novice interview.', 'Email report from campus coordinator'));

  // Tara has been eligible for a while; one nudge already sent to Yash
  at(daysAgo(1), () => S.nudgeStudent(db, ADMIN, sid['Yash']));

  db.notifications.forEach(n => { if (new Date(n.createdAt).getTime() < daysAgo(3)) n.isRead = true; });
  clock.set(null);
  return db;
}

export const DEMO_ACCOUNTS = {
  STUDENT: { userId: 'u_st_01', label: 'Aarav Sharma', hint: 'Eligible, not booked yet' },
  INTERVIEWER: { userId: 'u_iv_meera', label: 'Meera Iyer', hint: 'Has interviews today' },
  ADMIN: { userId: 'u_admin1', label: 'Priya Menon', hint: 'Ops lead · integrity reviewer' },
};
